-- =============================================================
-- Textos editables de las páginas
-- Ejecutar en: Supabase Dashboard > SQL Editor > New query
-- Proyecto: gmcuzmsckwtdvurboobh
-- Requiere: secciones_visibilidad.sql y contenido_secciones.sql
--
-- Hace editables desde admin.html > "Contenido de secciones" los
-- 123 textos de las páginas (títulos y párrafos) que en el HTML
-- llevan data-contenido="clave":
--
-- 1) Registra cada texto en informacion_general: así aparece en el
--    desplegable del panel y se puede ocultar desde "Secciones de la web".
-- 2) Copia a contenido_secciones el texto que hoy tiene la página, para
--    que el editor lo muestre listo para modificar.
--
-- Formato: el editor guarda una línea por <p> y las líneas vacías como
-- <p><br></p>. En títulos y párrafos, assets/js/secciones.js pone esas
-- líneas separadas con <br>, sin cambiar el estilo del elemento.
-- Las claves global.* (pie de página) se usan en todas las páginas.
--
-- Se puede ejecutar más de una vez: no pisa los textos editados en el
-- panel ni lo que se haya ocultado.
-- =============================================================

-- 1) Catálogo de textos
on conflict (clave) do update set
  pagina = excluded.pagina,
  titulo = excluded.titulo,
  orden  = excluded.orden;

-- 2) Texto actual de cada página
on conflict (seccion_clave) do nothing;
